        var accounts: [PersistentAccount]

        @Relationship(deleteRule: .nullify, inverse: \PersistentIdentity.wallet)
        var identities: [PersistentIdentity]

        init(
            walletId: Data,
            walletGroupId: Data = Data(),
            network: Network? = nil,
            name: String? = nil,
            walletDescription: String? = nil,
            birthHeight: UInt32 = 0,
