extension DashSchemaV5.PersistentWallet {
    var label: String {
        if let name = name, !name.isEmpty {
            return name
        }
        let hex = walletId.prefix(4)
            .map { String(format: "%02x", $0) }
            .joined()
        return hex.isEmpty ? "Wallet" : "Wallet \(hex)…"
    }
}

extension DashSchemaV5.PersistentWallet {
    static func predicate(walletId: Data) -> Predicate<DashSchemaV5.PersistentWallet> {
        #Predicate<DashSchemaV5.PersistentWallet> { $0.walletId == walletId }
    }

    static func predicate(
        walletGroupId: Data
    ) -> Predicate<DashSchemaV5.PersistentWallet> {
        #Predicate<DashSchemaV5.PersistentWallet> { $0.walletGroupId == walletGroupId }
    }
}
